import{_ as t,o,c as e,y as l}from"./chunks/framework.CNTkXYA8.js";const i=JSON.parse('{"title":"【C++程序不输出】到底是什么造成了程序不输出","description":"","frontmatter":{"title":"【C++程序不输出】到底是什么造成了程序不输出","date":"2018-12-02T20:44:00.000Z"},"headers":[],"relativePath":"blog/post-10055164.md","filePath":"source/old_posts/post-10055164.md"}'),s={name:"blog/post-10055164.md"};function a(n,p,r,_,c,d){return o(),e("div",null,[...p[0]||(p[0]=[l("<p>（ubuntu 16.04）</p><p>最近做题的时候，经常莫名其妙地，程序写的明明没毛病但是就是输出不了，气得我呀</p><p>然后某一次突然发现了原因，竟然是输出之后没有加endl或者空格！</p><p>例如：</p><p>cout&lt;&lt;1;</p><p>printf(1);</p><p>这样的不会输出</p><p>而</p><p>cout&lt;&lt;1&lt;&lt;endl;</p><p>cout&lt;&lt;1&lt;&lt;&quot; &quot;;</p><p>（printf同）</p><p>会输出</p><p>IDE中发现这个bug之后，以为是IDE的bug</p><p>然后我就在命令行</p><p>g++ -Wall xxx.cpp -o xxx</p><p>编译之后，发现规律是同样的</p><p>—— —— —— —— —— —— —— —— —— —— ——</p><p>目前的办法是加换行或者空格，具体原因不明（也许是特性吧）</p><p>待解决，在Windows下没有出现这种问题</p><p>—— —— —— —— —— —— —— —— —— —— ——</p><p>哦不！我意识到问题所在了！这种问题不符合常理！！！那么！！它是一个超自然力量！</p><p>这是模因危害！！！有一个人看到这篇文章！！它就会被传播一次！！</p>",22)])])}const f=t(s,[["render",a]]);export{i as __pageData,f as default};
